public class ArrayStack<T> implements IGenStack<T>{private final T[]data;private int size;public ArrayStack(T[]data){this.data=data;}public void push(T value)throws StackFullException{if(size==data.length)throw new StackFullException(size);data[size++]=value;}public T pop()throws StackEmptyException{if(size==0)throw new StackEmptyException("empty");T first=data[0];System.arraycopy(data,1,data,0,--size);return first;}}
